import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"决策表","description":"","frontmatter":{},"headers":[],"relativePath":"guide/decision-tables.md","filePath":"guide/decision-tables.md","lastUpdated":1792083553000}'),r={name:"guide/decision-tables.md"};function c(i,t,l,n,h,s){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="决策表" tabindex="-1">决策表 <a class="header-anchor" href="#决策表" aria-label="Permalink to &quot;决策表&quot;">​</a></h1><p>决策表让角色按一组有序规则选择行动，例如低生命时治疗、敌人聚集时释放范围技能、最后使用普攻。规则只表达行动意图，仍须满足当前状态、决策点、配额、资源、目标与射程限制。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><p>当前版本支持 <code>beforeDecision</code>，在角色普通 AI 决策前评估。多行动回合每次需要新决策时重新匹配，不是整回合只查一次。</p><table tabindex="0"><thead><tr><th>优先顺序</th><th>处理</th></tr></thead><tbody><tr><td>1</td><td>宿主已明确选择的动作</td></tr><tr><td>2</td><td>AI 确认已有有效协同申请</td></tr><tr><td>3</td><td>当前行动角色绑定的决策表</td></tr><tr><td>4</td><td>表未命中时的回退：默认 AI，或结束回合</td></tr></tbody></table><p>决策表通过 AI 控制器接入。手动角色的普通行动不会自动按表执行；<code>EnableAI = false</code> 时不评估角色策略。AI 协作方使用自己的表向当前行动者提交原地申请，与当前行动者是否为手动玩家无关。手动控制的协作方由宿主显式提交，不被 AI 代选；协同不能移动。</p><h2 id="怎样匹配" tabindex="-1">怎样匹配 <a class="header-anchor" href="#怎样匹配" aria-label="Permalink to &quot;怎样匹配&quot;">​</a></h2><p>规则的 <code>priority</code> 越大越先尝试，同优先级按配置顺序。禁用的规则跳过。每条规则先尝试合法目标、站位及施法方案，再对同一方案检查条件；条件成立且动作可执行才算命中。</p><p>无法执行时继续尝试后面的规则。例如，治疗规则满足生命条件，但技能冷却、资源不足或没有合法目标，就继续考虑范围攻击或普攻。规则表不会强行执行非法动作，也不会绕过宿主筛选的目标或禁用的动作类别。</p><p>全部未命中时，<code>defaultAI</code> 使用当前 AI 模式继续决策，<code>endTurn</code> 则结束回合。空表配合 <code>defaultAI</code> 可用于保留默认行为。显式 <code>endTurn</code> 动作是有效决策，表示主动结束，而非“继续匹配”。</p><p>规则搜索共用策略总方案预算，额度按剩余规则分配，未用部分留给后续规则；默认 AI 回退使用独立预算。候选被截断时，“未命中”只代表已检查的方案未命中，不代表所有合法方案都已穷举。具体分配和诊断见<a href="./../dev/decision-tables.html#规则预算">规则预算</a>。</p><h2 id="目标、移动与位置" tabindex="-1">目标、移动与位置 <a class="header-anchor" href="#目标、移动与位置" aria-label="Permalink to &quot;目标、移动与位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>含义</th></tr></thead><tbody><tr><td><code>self</code></td><td>自身</td></tr><tr><td><code>ally</code></td><td>友方，包含自身；实际还要满足技能的目标条件</td></tr><tr><td><code>enemy</code></td><td>敌方</td></tr><tr><td><code>lowestHpRatio</code> / <code>highestHpRatio</code></td><td>按生命比例排序</td></tr><tr><td><code>nearest</code></td><td>按距离排序</td></tr><tr><td><code>movement: never</code></td><td>禁止移动</td></tr><tr><td><code>movement: ifNeeded</code></td><td>允许按方案选择位置</td></tr><tr><td><code>movement: required</code></td><td>必须移动才能执行</td></tr><tr><td><code>positionPreference: current</code></td><td>优先移动成本低的方案</td></tr><tr><td><code>positionPreference: coverage</code></td><td>优先覆盖更多合法目标，其次移动成本与风险</td></tr><tr><td><code>positionPreference: safe</code></td><td>优先低风险，其次覆盖数与移动成本</td></tr></tbody></table><p>绑定名只在当前规则内有效。范围条件 <code>plan.targetCount</code> 统计选中方案的合法角色覆盖数，不是格子数，也不是地图上的敌人总数。</p><p>无地图时，<code>distance</code>、<code>plan.risk</code> 条件不匹配，强制移动、接近和撤退动作不可执行；允许按需移动的技能仍可原地规划。协同行动始终禁止移动，表内的 <code>endTurn</code> 表示不提交协同申请。</p><h2 id="执行前重验" tabindex="-1">执行前重验 <a class="header-anchor" href="#执行前重验" aria-label="Permalink to &quot;执行前重验&quot;">​</a></h2><p>规划完成后，队列会在移动前、动作开始后及询问后重新检查。若目标死亡、资源变化或施法位置失效，当前尝试会跳过失效规则并按有限重试继续决策。已经成功的移动不会回滚，后续规划从角色真实位置执行。</p><p>安全位置使用当前存活且可行动敌人的移动与射程估算威胁数量。风险为 0 也不保证吟唱绝对安全：它不会预测隐藏效果、敌人策略或队友保护。候选预算属于近似搜索，不能保证每个局面都找到最优解。</p><p>规则的各种位置偏好均使用实际风险；新 AI 模式的普攻、物品、即时技能和吟唱技能也按实际位置参与风险扣分。计算风险本身不要求移动或搜索更多站位，默认模式仍是 <code>Legacy</code>。</p><h2 id="继续阅读" tabindex="-1">继续阅读 <a class="header-anchor" href="#继续阅读" aria-label="Permalink to &quot;继续阅读&quot;">​</a></h2><ul><li><a href="./../dev/decision-tables.html">编写、加载与绑定决策表</a></li><li><a href="./../dev/decision-table-editor.html">可视化决策表编辑器</a></li><li><a href="./../dev/decision-table-boss.html">完整 BOSS 决策表</a></li><li><a href="./../dev/ai-planning.html">AI 模式与施法规划</a></li><li><a href="./chain-action.html">协同行动</a></li></ul>',21)])])}const f=e(r,[["render",c]]);export{b as __pageData,f as default};
